  "shortcuts.group.help": "Справка",
  "shortcuts.commandSearch": "Открыть поиск команд",
  "interactiveHelp.title": "Интерактивная справка",
  "interactiveHelp.subtitle": "Нажмите на любой элемент, чтобы прочитать о нём",
  "interactiveHelp.named": "«{name}»",
  "interactiveHelp.close": "Закрыть окно справки",
  "interactiveHelp.nothing": "Здесь нечего объяснять. Укажите на кнопку, поле, маркер или окно.",
  "interactiveHelp.loading": "Ищу в руководстве ...",
  "interactiveHelp.noIndex": "Руководство здесь пока недоступно. Откройте его из обзора.",
  "interactiveHelp.panelOnly": "У этого элемента нет собственного названия. Значок вопроса его окна открывает часть руководства о нём.",
  "interactiveHelp.sectionOnly": "В руководстве есть раздел об этой части.",
  "interactiveHelp.noMatch": "В руководстве пока ничего нет о «{name}». Попробуйте поиск.",
  "interactiveHelp.also": "Также в руководстве",
  "interactiveHelp.search": "Искать в руководстве",
  "interactiveHelp.open": "Открыть в руководстве",
  "interactiveHelp.started": "Интерактивная справка включена: нажмите кнопку, поле или окно, чтобы прочитать о нём. Esc выключает её.",
  "interactiveHelp.ended": "Интерактивная справка выключена",
  "shortcuts.interactiveHelp": "Включить или выключить интерактивную справку",
  "installHint.chromium": "Установите его через значок справа от адресной строки или из меню браузера в разделе «Установить как приложение».",
  "installHint.safariMac": "В Safari: меню «Файл» → «Добавить в Dock».",
  "installHint.ios": "В Safari: значок «Поделиться» → «Добавить на экран Домой».",
  "installHint.firefox": "Firefox не умеет устанавливать приложения — но layerling всё равно запускается офлайн прямо во вкладке.",
  "welcome.moreLanguagesTitle": "Ваш язык",
  "welcome.moreLanguagesBody": "программа и её руководство говорят по-английски, по-немецки и ещё на 17 языках; список языков находится в самом верху справа и в настройках на стартовой странице.",
  "welcome.moreOfflineTitle": "Работает офлайн",
  "welcome.moreOfflineBody": "после первого посещения layerling запускается и без интернета — установите его как обычную программу, и ваши проекты останутся на вашем компьютере.",
  "welcome.moreAiTitle": "Создание с помощью ИИ",
  "welcome.moreAiBody": "через интерфейс MCP ИИ-помощник может создавать и редактировать фигуры; в редакторе он открывается сам. Для этого нужна собственная копия layerling (npm run dev или Docker-образ); на layerling.com подключение ИИ отключено.",
  "welcome.morePointsTitle": "Опорные точки",
  "welcome.moreSearchTitle": "Поиск команд",
  "welcome.moreSimplifyTitle": "Упрощение полигональных сеток",
  "welcome.moreSimplifyBody": "импортированная полигональная сетка с огромным числом треугольников сокращается до доли исходной — с просмотром «до/после» и ползунком, чтобы разрезание, группировка и перетаскивание оставались плавными.",
  "welcome.moreHistoryTitle": "История",
  "welcome.moreLookTitle": "Внешний вид на ваш вкус",
  "welcome.moreLookBody": "В настройках можно задать фон и рабочую плоскость, стрелки осей X, Y и Z, линии кромок на всех телах, цвета эскизов, контрастность, тени и направление света — например, чтобы тёмные тела не сливались. На слабых компьютерах быстрый режим мгновенно отключает всё ресурсоёмкое.",
  "welcome.moreHistoryBody": "просматривайте любое предыдущее состояние проекта с помощью ползунка, ничего не меняя, — экспортируйте это состояние или создайте на его основе новый проект.",
  "welcome.moreDrawingTitle": "Чертёж для мастерской",
  "welcome.moreDrawingBody": "Экспорт → Чертёж: виды спереди, сверху и сбоку в масштабе 1:1 на листе ISO, с габаритными размерами, невидимыми кромками и таблицей круглых отверстий — в PDF или SVG, чтобы распечатать или отнести к токарному или фрезерному станку.",
  "welcome.moreSearchBody": "Нажмите Ctrl+K и введите название инструмента, фигуры или команды, чтобы сразу перейти к ней — поиск работает на английском и русском, рядом показаны сочетания клавиш. Тела вашего проекта также находятся по имени.",
  "welcome.morePointsBody": "щёлкните правой кнопкой мыши по телу, чтобы отметить его центр, углы или середины кромок точками, которые не печатаются, но служат ориентиром для привязки фигур — так вы точно разместите отверстие по центру другой детали.",
  "welcome.videosTitle": "Видео о layerling",
  "welcome.videosHint": "Сделаны другими людьми, а не этим проектом. Ссылки открывают YouTube в новой вкладке; оттуда ничего не загружается, пока вы не нажмёте.",
  "welcome.help": "В редакторе в группе «Справка» — краткое руководство и список всех сочетаний клавиш. Кнопка «Сообщить об ошибке» в нижнем колонтитуле сохраняет проект со всем, что нужно для отчёта на форуме или на GitHub.",
  "welcome.guideLink": "Открыть полное руководство пользователя, с картинками",
  "welcome.guideUrl": "/ru/index.html",
