  "cookieCutter.name": "Формочка для печенья",
  "cookieCutter.subtitle": "Стенка и бортик вокруг контура",
  "cookieCutter.cancel": "Закрыть формочку",
  "cookieCutter.help": "Контур выделения становится тонкой стенкой с режущей кромкой и плоским бортиком у основания. Отверстия в нём, например внутренность буквы e, получают свои стенки. Стенку, высоту и бортик потом можно изменить в свойствах.",
  "cookieCutter.support": "Внутренние стенки держат",
  "cookieCutter.support.bridges": "Перемычки",
  "cookieCutter.support.plate": "Пластина",
  "cookieCutter.supportBridgesHint": "Перемычки со стороны, на которую вы давите, соединяют внутренние стенки с внешней.",
  "cookieCutter.supportPlateHint": "Тонкая пластина заполняет весь контур со стороны, на которую вы давите: прочнее и лучше держится на столе, но тесто нельзя выдавить сзади.",
  "cookieCutter.plate": "Толщина пластины",
  "cookieCutter.fillet": "Галтели",
  "cookieCutter.filletHint": "Небольшой скос там, где стенки стоят на бортике, перемычках или пластине, чтобы тонкие части не отламывались. 0 — без них.",
  "cookieCutter.imprint": "Внутренние стенки ниже на",
  "cookieCutter.imprintHint": "0 вырезает внутренность. Более низкие внутренние стенки только выдавливают её: при стенке 15 мм и тесте 5 мм на 3 мм ниже — 2 мм в глубину.",
  "cookieCutter.mirror": "Отзеркалить контур (текст выходит правильно)",
