  "status.cookieCutterNeedsShape": "Сначала выдели фигуру или эскиз.",
  "status.cookieCutterNoOutline": "У этой фигуры нет контура на рабочей плоскости, из которого можно сделать формочку. Сначала поставь её на рабочую плоскость.",
