  "status.cookieCutterMadeFlat": "Формочка готова, сверху плоская: у контура есть ступеньки, слишком короткие для режущей кромки. Стенку можно изменить в свойствах.",
  "editor.tool.flexi": "Флекси-шарниры",
  "flexi.title": "Флекси-шарниры",
  "flexi.subtitle": "Разрезать плоское тело на подвижные звенья",
  "flexi.cancel": "Закрыть флекси-шарниры",
  "flexi.help": "Тело разрезается поперёк длины на звенья, и в каждом разрезе появляется шарнир, который печатается сразу на месте. После печати звенья поворачиваются в стороны. Сначала положите тело плашмя на стол; там, где будут шарниры, оно должно быть не меньше примерно 6 мм в высоту и 12 мм в ширину.",
