  "flexi.error.tooShort": "Шарниры не помещаются по длине тела. Возьмите меньше шарниров или сдвиньте первый и последний ближе к середине.",
  "flexi.error.tooThin": "Шарниру {joint} не хватает места: тело там шириной всего {size} мм. Сделайте его там шире, возьмите шарнир поменьше или сдвиньте шарниры.",
