  "shell.edges.round": "Скруглённые",
  "shell.edges.sharp": "Острые",
  "shell.edgesHint": "Применяется там, где внутренние стенки расходятся: на уступе или у проёма. Углы обычного прямоугольного тела внутри останутся острыми — сначала скруглите внешние кромки, чтобы скруглёнными были и внутренние.",
  "shell.apply": "Создать оболочку",
