  "shell.errorTooThick": "Для этого тела стенки не могут быть такими толстыми. Выберите меньшую толщину.",
  "shell.errorRoundedEdges": "У этой коробки скруглены верхние и нижние рёбра, и стенка должна быть заметно тоньше этого скругления. Выберите меньшую толщину или поставьте скругление верхних и нижних рёбер на 0, прежде чем выдалбливать. Если снова не получится, «Сообщить об ошибке» внизу страницы сохранит проект для сообщения.",
  "shell.errorCannotHollow": "Это тело нельзя сделать полым даже с очень тонкой стенкой. Вероятно, его контур недостаточно чист для ядра CAD; причиной может быть вырез, касающийся внешней кромки, например дверной проём, доходящий до нижнего края импортированной фигуры.",
  "shell.errorNoFlatTop": "У этого тела нет плоской верхней грани, которую можно оставить открытой. Сферы и свободные фигуры нельзя сделать полыми этим способом.",
  "shell.errorNoFlatBottom": "У этого тела нет плоской нижней грани, которую можно оставить открытой.",
  "edge.errorOldRevolve": "Это тело вращения было построено как полигональная сетка в старой версии layerling. Откройте «Изменить эскиз» и завершите построение заново, чтобы получить точное тело; после этого его можно сделать полым, скруглить или снять фаску.",
  "shell.errorNoFlatSide": "На выбранной стороне этого тела нет плоской грани, которую можно оставить открытой.",
  "shell.errorProjectChanged": "Объект или проект изменился во время создания оболочки; попробуйте ещё раз.",
