  "historyStep.offsetOne": "Смещено: {name}",
  "historyStep.offsetMany": "Смещено объектов: {count}",
  "guide.edges.offset": "Смещение сдвигает каждую грань тела на одно расстояние наружу или внутрь. Увеличьте копию и оставьте её как отверстие, чтобы получить зазор посадки, или уменьшите тело для штифта, который должен входить в отверстие. Тела, заданные только сеткой треугольников, часто нельзя сместить.",
  "edge.revertSurfaceTexture": "Текстура поверхности (глубина {size} мм)",
  "deleteFace.title": "Удалить грань",
  "deleteFace.subtitle": "Соседние грани закрывают разрыв",
  "deleteFace.help": "Щёлкните грани, которые нужно удалить; повторный щелчок снимает выбор с грани. Соседние грани растут, пока разрыв не закроется: скругление, отверстие или бобышка исчезают, а тело остаётся точным.",
  "deleteFace.preparing": "Чтение граней…",
  "deleteFace.countNone": "Грани ещё не выбраны",
  "deleteFace.countOne": "Выбрана 1 грань",
  "deleteFace.countMany": "Выбрано граней: {count}",
  "deleteFace.apply": "Удалить",
  "deleteFace.working": "Удаление граней…",
  "deleteFace.cancel": "Отменить удаление граней",
  "deleteFace.errorUnchanged": "Эти грани нельзя удалить: соседние грани не закрывают разрыв. Выберите все грани того, что нужно убрать, например все грани скругления или всю стенку отверстия, и ни одной грани самого тела.",
  "deleteFace.errorMesh": "У этого тела нет точных граней для удаления: layerling хранит его как сетку — как импортированный STL, OBJ или 3MF, разделённое, обёрнутое вокруг цилиндра или упрощённое тело или очень детальную фигуру, например длинный текст. У детали, импортированной как STEP, точные грани есть.",
  "deleteFace.errorResized": "Размер этого тела изменили при включённом параметре «Сохранять размер обработки кромки при изменении размера тела», поэтому его точные грани больше не соответствуют размеру. Отмените изменение размера, удалите грани, затем снова измените размер.",
  "deleteFace.errorProjectChanged": "Объект или проект изменился во время удаления граней; попробуйте ещё раз.",
  "deleteFace.errorFailed": "Не удалось удалить грани. Выберите другие грани.",
  "deleteFace.errorNoFaces": "Не удалось прочитать грани этого тела. Закройте инструмент и откройте его снова.",
  "deleteFace.errorTooSlow": "Удаление этих граней заняло слишком много времени и было остановлено через 45 секунд; ничего не изменилось. Ядро CAD не справляется с этими гранями на этой детали: выберите другие грани или меньше граней.",
  "status.facesDeletedOne": "Удалена 1 грань",
  "status.facesDeletedMany": "Удалено граней: {count}",
  "status.facesDeletedMcpOne": "Удалена 1 грань через MCP",
