  "status.honeycombConverted": "Сотовая структура преобразована в массив отверстий: {count}",
  "welcome.moreHolePatternTitle": "Массив отверстий",
  "welcome.moreHolePatternBody": "Щёлкните по плоской грани тела и распределите по ней отверстия: круглые, квадратные, прямоугольные, шестигранные или щелевидные, сеткой или в шахматном порядке, с шагом, отступом от края и глубиной (сквозные или заданной глубины). Предпросмотр показывает отверстия до их создания; они остаются обычными отверстиями, сгруппированными с телом — для вентиляции, решёток динамиков, корзинок и корпусов.",
  "welcome.moreTextureTitle": "Текстура поверхности",
  "welcome.moreTextureBody": "наносит рельеф на любое тело — для хвата или для красоты: накатка, канавки, соты, древесная текстура, канат, картинка как карта высот или текст, вокруг круглых тел или плоско вдоль оси.",
  "welcome.moreVaseTitle": "Вазы и горшки",
  "welcome.moreVaseBody": "отдельная фигура для ваз, горшков и абажуров: форма корпуса, сечение, закрутка, узоры, дренажные отверстия, поддон и крышка — сплошная для режима вазы в слайсере или полая.",
  "welcome.moreOffsetTitle": "Смещение и вырезание",
  "welcome.moreOffsetBody": "увеличивает или уменьшает точное тело на заданное расстояние — для зазора посадки с натягом — или за один шаг вырезает одну деталь из другой с зазором по всему контуру.",
  "guide.select.holePattern": "Массив отверстий (кнопка на панели инструментов рядом с «Массив», правый щелчок по телу или Ctrl+K): щёлкните по плоской грани, затем задайте форму, размер, шаг, порядок, отступ и глубину отверстий. Отверстия отображаются в предпросмотре; «Создать» добавляет их как отверстия, сгруппированные с телом. Разгруппировка снова отделяет их.",
  "guide.select.faceTool": "Грань (кнопка на панели инструментов рядом с «Массив отверстий», правый щелчок по телу или Ctrl+K): щёлкните по плоской грани, выберите «Наружу» или «Внутрь», затем задайте отступ от края, радиус углов и глубину. Добавляется тело из эскиза, сгруппированное с телом.",
  "scalePercent.errorTooSmall": "«{name}» станет меньше 0,01 мм.",
  "scalePercent.errorTooLarge": "«{name}» станет больше, чем допускает её форма. Задайте больший «Лимит пользовательского размера» в разделе «Параметры фигур по умолчанию» в настройках или выберите меньший процент.",
