  "gear.rackHint": "Шаг {pitchLength} мм на зуб; длина = число зубьев × шаг. По рейке катится шестерня модуля {module}: её центр отстоит от делительной прямой на число зубьев × модуль / 2, а сама прямая — на {offset} мм от вершин зубьев.",
  "gear.rackRoundHint": "Круглые зубья, шаг {pitchLength} мм на зуб; длина = число зубьев × шаг. По рейке катится шестерня с круглыми зубьями модуля {module}: её центр отстоит от делительной прямой на число зубьев × модуль / 2, а сама прямая — на {offset} мм от вершин зубьев.",
