  "hinge.leafFingers": "Пальцы",
  "hinge.leafFingersHint": "Каждое звено несёт свой палец; пальцы двух сторон чередуются, как два гребня. Так петля поворачивается полностью, а с конусами и пальцами толщиной со звено складывается плоско. Пальцы одной стороны не соединены полотном: соедините их со своей моделью, например с коробкой и крышкой.",
