  "prop.hingeScrewAcrossHint": "От отверстия в одном полотне до отверстия в другом, от центра до центра. 0 ставит каждое отверстие посередине своего полотна.",
  "prop.gridfinityType": "Тип",
  "gridfinity.bin": "Контейнер",
  "gridfinity.baseplate": "Базовая плита",
  "gridfinity.binHint": "Контейнер на сетке Gridfinity с шагом 42 мм: он встаёт в базовую плиту и ставится на другие контейнеры — в том числе из других генераторов Gridfinity.",
  "gridfinity.baseplateHint": "Плита, в которую встают контейнеры Gridfinity, высотой 5 мм: по гнезду на каждую ячейку сетки 42 мм.",
  "gridfinity.tray": "Лоток",
  "gridfinity.trayHint": "Лоток любого размера в мм с плоским дном, для вставок в настольные игры и мелких деталей: без ножек и без штабельного бортика, поэтому он не встаёт в базовую плиту и не ставится в штабель. Перегородки и полки для этикеток доходят до верха.",
  "prop.gridfinityUnitsX": "Ячеек по ширине",
  "prop.gridfinityUnitsZ": "Ячеек по глубине",
  "prop.gridfinityUnitsY": "Единиц высоты",
  "prop.gridfinityLip": "Штабельный бортик",
  "prop.gridfinityLipChamfer": "Фаска бортика",
  "gridfinity.lipChamferHint": "Снимает фаску с верхней кромки штабельного бортика; при 0 кромка остаётся острой, как в спецификации Gridfinity.",
  "prop.gridfinityMagnets": "Отверстия под магниты",
  "prop.gridfinityHalfGrid": "Половинная сетка (21 мм)",
  "gridfinity.halfGridHint": "Ширина и глубина считаются в клетках по 21 мм, у каждой своя ножка; четыре встают в одно гнездо базовой плиты.",
  "prop.gridfinityFloorHeight": "Высота дна",
  "gridfinity.floorHeightHint": "До этой высоты, считая от низа, контейнер сплошной: заготовка, в которой можно вырезать формы.",
  "prop.gridfinityWallThickness": "Толщина стенок",
  "gridfinity.wallThicknessHint": "Стенка отсчитывается от наружной стороны, которая не меняется. Со штабельным бортиком стенка толще 1,75 мм заканчивается уступом на 0,85 мм ниже отметки 7 мм на единицу высоты, не задевая ножки контейнера сверху.",
  "prop.gridfinityOpenBack": "Открыт сзади",
  "prop.gridfinityOpenFront": "Открыт спереди",
  "prop.gridfinityOpenLeft": "Открыт слева",
  "prop.gridfinityOpenRight": "Открыт справа",
