  "prop.gridfinityOpeningDistanceBack": "Отступ сзади",
  "prop.gridfinityOpeningDistanceFront": "Отступ спереди",
  "prop.gridfinityOpeningDistanceLeft": "Отступ слева",
  "prop.gridfinityOpeningDistanceRight": "Отступ справа",
  "gridfinity.openingHint": "Глубина считается от верха бортика (без бортика от верха контейнера), отступ от того края, у которого стоит проём. На всю ширину до дна сторона открыта полностью; проём поменьше оставляет углы стороны и бортик рядом с ним.",
  "prop.gridfinityOpeningCorner": "Углы проёма",
  "prop.gridfinityOpeningCornerSize": "Размер углов проёма",
  "gridfinity.openingCornerHint": "Верхние и нижние углы проёмов, если смотреть на стенку снаружи; при размере меньше 0,5 мм они остаются прямыми. У проёма на всю сторону верхних углов нет.",
  "prop.gridfinityPaddingBack": "Кайма сзади",
  "prop.gridfinityPaddingFront": "Кайма спереди",
  "prop.gridfinityPaddingLeft": "Кайма слева",
  "prop.gridfinityPaddingRight": "Кайма справа",
  "gridfinity.paddingHint": "Сплошная кайма снаружи сетки, чтобы базовая плита заполнила ящик, размер которого не кратен единицам. При её изменении число единиц сохраняется, а размер плиты меняется вместе с ней.",
  "prop.gridfinityCornerRadius": "Радиус углов",
  "gridfinity.cornerRadiusHint": "Радиус четырёх внешних углов плиты: 4 мм, как в спецификации Gridfinity, вплоть до 0 для прямых углов, которые встают в углы ящика. Гнёзда сохраняют своё скругление, так что контейнеры встают как прежде.",
  "gridfinity.binCornerRadiusHint": "Радиус внешних углов контейнера выше ножек: 3,75 мм, как в спецификации Gridfinity, вплоть до 0 для прямых углов, чтобы контейнеры, стоящие рядом в ящике, и там, где сходятся четыре, оставляли только свои зазоры 0,5 мм. Ножки, внутренняя часть и скосы штабельного бортика сохраняют своё скругление, так что контейнер встаёт в плиту и ставится в стопку как прежде.",
  "prop.gridfinityDrawerWidth": "Ширина ящика",
  "prop.gridfinityDrawerDepth": "Глубина ящика",
  "gridfinity.drawerHint": "Внутренний размер ящика; плита выходит на 0,5 мм меньше. Для ящика больше 334,5 мм или больше печатного стола нужно несколько плит.",
  "prop.gridfinityLabelBack": "Полка для этикетки сзади",
  "prop.gridfinityLabelFront": "Полка для этикетки спереди",
  "prop.gridfinityLabelLeft": "Полка для этикетки слева",
  "prop.gridfinityLabelRight": "Полка для этикетки справа",
