  "vaseCheck.slitsKept": "Слайсер: спиральный режим вазы включён, ширина внешней линии {line} мм (как задано здесь). Прорези ({slit} мм) сохраняются при стандартных настройках; две линии ребра лежат в {slit} мм друг от друга. Прочно сплавить: ширина прорези 0,03 мм и в слайсере «Slice gap closing radius» 0,01 мм (PrusaSlicer, OrcaSlicer, Bambu Studio).",
  "vaseCheck.slitsGap": "Слайсер: спиральный режим вазы включён, ширина внешней линии {line} мм (как задано здесь). Важно: поставьте «Slice gap closing radius» (PrusaSlicer, OrcaSlicer, Bambu Studio) не больше {radius} мм — иначе слайсер закроет прорези {slit} мм и напечатает простую стенку.",
