  "export.3mf.description": "Проект слайсера с цветами",
  "export.3mf.note": "Для PrusaSlicer, Bambu Studio, OrcaSlicer и Cura. Каждое тело остаётся отдельной деталью со своим именем и цветом.",
  "export.obj.description": "Универсальная 3D-сетка",
  "export.obj.note": "Широко совместимый формат сетки для моделирования, визуализации и обмена. Цвета хранятся в вершинах, их читают Bambu Studio и OrcaSlicer.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Сохраняет кубы, цилиндры, сферы и конусы как точную CAD-геометрию, а также всё, у чего скруглены или срезаны фаской кромки, и тела, импортированные как STEP. Резьба, пружины и шестерни тоже передаются точным телом. Сужающиеся, наклонённые и скрученные тела тоже передаются точно. А вот импортированные сетки STEP не поддерживает — они идут как STL.",
  "export.svg.description": "Вектор вида сверху",
  "export.svg.note": "Экспортирует чистый силуэт вида сверху в миллиметрах, включая отверстия и криволинейные контуры.",
  "export.svg.noteFootprint": "Экспортирует только контуры, которыми объекты стоят на рабочей плоскости, линиями в миллиметрах, для лазерной резки и шаблонов.",
  "export.svg.noteEdges": "Экспортирует видимые сверху рёбра линиями в миллиметрах, каждое тело своим цветом: контуры, отверстия, карманы и гравировки, каждая область замкнута, для лазерной гравировки и плоттеров.",
  "export.svg.view": "Вид",
  "export.svg.viewSilhouette": "Силуэт сверху",
  "export.svg.viewFootprint": "След на рабочей плоскости",
  "export.bridges": "Перемычки для выпадающих частей",
  "export.bridgesHint": "Часть внутри выреза (середина «о», брюшко «b») выпадает, если её вырезать по кругу. Маленькие перемычки держат её на месте, как на трафарете.",
  "export.bridgeWidth": "Ширина перемычки",
  "export.bridgeCount": "Перемычек на часть",
  "export.svg.viewEdges": "Видимые рёбра сверху",
  "export.dxf.description": "Контур для лазерной резки",
  "export.dxf.note": "Экспортирует контур сверху для мастерских лазерной резки: отрезки, настоящие дуги и окружности на слое 0 белым цветом, в миллиметрах. Соприкасающиеся тела дают один контур.",
  "export.dxf.noteFootprint": "Экспортирует только контуры, которыми объекты стоят на рабочей плоскости, для мастерских лазерной резки: отрезки, настоящие дуги и окружности на слое 0 белым цветом, в миллиметрах.",
  "export.lyl.description": "Собственный формат проектов layerling",
  "export.lyl.note": "Сохраняет редактируемый проект, историю отмен и возвратов, эскизы, группы, CAD-данные и импортированные исходники. Старые файлы .skf тоже открываются и сохраняются как .lyl. В Chrome и Edge вы выбираете папку и имя файла сами, и Ctrl+S затем снова сохраняет в тот же файл; проект, открытый из файла, сохраняется обратно в него.",
  "import.openProject": "Открыть проект layerling",
