  "import.insertProject": "Вставить в этот проект",
  "import.insertProjectHint": "Добавить тела из проекта layerling (.lyl) к уже открытым — например, базовые детали, которые вы используете снова и снова",
  "import.referenceImage": "Эталонное изображение",
